actions.script:
def _o = ec.user.getPreference('ACTIVE_ORGANIZATION'); def _can = false
try { if (ec.user.isInGroup("ADMIN")) _can = true else { def _z = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }; _can = !(_z.size()==1 && _z.contains("ZENITH_CASHIER")) } } catch (Exception e) {}
if (_can && _o && _o != '_NA_') {
    if (ec.context.dd == 'home') ec.entity.find("zenith.erp.pos.OrgDashboardDefault").condition("organizationPartyId", _o).deleteAll()
    else ec.entity.makeValue("zenith.erp.pos.OrgDashboardDefault").set("organizationPartyId", _o).set("dashboardKey", "pos").createOrUpdate()
}

def sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
def now = ec.user.nowTimestamp
def todayStr = sdf.format(now)
if (!dashDate) dashDate = todayStr
if (!dashDateTo) dashDateTo = dashDate
if (!dashLoc) dashLoc = ''
// keep From <= To (swap if the user picks them backwards)
if (dashDateTo < dashDate) { def _sw = dashDate; dashDate = dashDateTo; dashDateTo = _sw }

def dayStart = java.sql.Timestamp.valueOf(dashDate + " 00:00:00")
def dayEnd = java.sql.Timestamp.valueOf(dashDateTo + " 23:59:59")

// Preset range anchors (each ends today)
def _cw = java.util.Calendar.getInstance(); _cw.setTime(now)
_cw.set(java.util.Calendar.DAY_OF_WEEK, _cw.getFirstDayOfWeek())
def weekStartStr = sdf.format(_cw.getTime())
def _cm = java.util.Calendar.getInstance(); _cm.setTime(now); _cm.set(java.util.Calendar.DAY_OF_MONTH, 1)
def monthStartStr = sdf.format(_cm.getTime())
def _c30 = java.util.Calendar.getInstance(); _c30.setTime(now); _c30.add(java.util.Calendar.DAY_OF_MONTH, -29)
def last30Str = sdf.format(_c30.getTime())

// active-preset detection (for chip highlight) + preset link URLs (relative query preserves the screen path)
presetActive = 'custom'
if (dashDateTo == todayStr) {
    if (dashDate == todayStr) presetActive = 'today'
    else if (dashDate == weekStartStr) presetActive = 'week'
    else if (dashDate == monthStartStr) presetActive = 'month'
    else if (dashDate == last30Str) presetActive = 'last30'
}
urlToday = "?dashDate=" + todayStr + "&dashDateTo=" + todayStr
urlWeek  = "?dashDate=" + weekStartStr + "&dashDateTo=" + todayStr
urlMonth = "?dashDate=" + monthStartStr + "&dashDateTo=" + todayStr
url30    = "?dashDate=" + last30Str + "&dashDateTo=" + todayStr
urlSettings = "?dashDate=" + dashDate + "&dashDateTo=" + dashDateTo + (dashLoc ? "&dashLoc="+dashLoc : "") + "&showSettings=1"

if (dashDate == dashDateTo) {
    displayDate = new java.text.SimpleDateFormat("dd MMM yyyy, EEEE").format(java.sql.Date.valueOf(dashDate))
} else {
    def _f1 = new java.text.SimpleDateFormat("dd MMM")
    def _f2 = new java.text.SimpleDateFormat("dd MMM yyyy")
    displayDate = _f1.format(java.sql.Date.valueOf(dashDate)) + " – " + _f2.format(java.sql.Date.valueOf(dashDateTo))
}

// ZE-DASH-04 (Owner View): mode-adaptive location filter — MUST be computed BEFORE the entity-finds
// below (which read _locSessionIds). Locations = the tenant's retail-store FACILITIES (branch/Owner-View)
// when it runs 2+ stores, else its TERMINALS/counters (multi-counter). Hidden for a single location.
// Transactions link via sessionId -> PosSession.terminalId -> Terminal.facilityId.
def _org = ec.user.getPreference("ACTIVE_ORGANIZATION")
// ZE-SHOP: the global shop switcher (ACTIVE_SHOP) drives this dashboard's store-mode filter unless the
// user picked a specific location chip on THIS page (explicit dashLoc always wins).
if (!dashLoc) { try { def _ass = ec.service.sync().name("zenith.base.ShopServices.get#ActiveShopScope").call(); if (_ass?.activeShopId) dashLoc = _ass.activeShopId } catch (Exception _ge) {} }
locMode = 'none'; locOptions = []; _locSessionIds = null
try {
    if (_org && _org != '_NA_') {
        def _terms = ec.entity.find("zenith.erp.pos.PosTerminal").condition("organizationPartyId", _org).list()
        if (_terms) {
            def _facIds = _terms.collect { it.facilityId }.findAll { it }.unique()
            def _stores = _facIds ? ec.entity.find("mantle.facility.Facility").condition("facilityId","in",_facIds).condition("facilityTypeEnumId","FcTpRetailStore").list() : []
            def _locTermIds = null
            if (_stores.size() >= 2) {
                locMode = 'store'
                _stores.sort { it.facilityName }.each { f -> locOptions.add([id:f.facilityId, name:f.facilityName, url:"?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&dashLoc="+f.facilityId]) }
                if (dashLoc) _locTermIds = _terms.findAll { it.facilityId == dashLoc }.collect { it.terminalId }
            } else if (_terms.size() >= 2) {
                locMode = 'counter'
                _terms.sort { (it.terminalName ?: it.terminalId) }.each { t -> locOptions.add([id:t.terminalId, name:(t.terminalName ?: t.terminalId), url:"?dashDate="+dashDate+"&dashDateTo="+dashDateTo+"&dashLoc="+t.terminalId]) }
                if (dashLoc) _locTermIds = [dashLoc]
            }
            if (_locTermIds) {
                def _ss = ec.entity.find("zenith.erp.pos.PosSession").condition("terminalId","in",_locTermIds).list()
                _locSessionIds = _ss ? _ss.collect { it.sessionId }.unique() : ['__NONE__']
            }
        }
    }
} catch (Exception e) { locMode = 'none'; _locSessionIds = null }
urlLocAll = "?dashDate="+dashDate+"&dashDateTo="+dashDateTo
locName = 'All ' + (locMode=='store' ? 'Shops' : 'Counters')
if (dashLoc) { def _o = locOptions.find { it.id == dashLoc }; if (_o) locName = _o.name }
if (dashLoc) { urlToday += "&dashLoc="+dashLoc; urlWeek += "&dashLoc="+dashLoc; urlMonth += "&dashLoc="+dashLoc; url30 += "&dashLoc="+dashLoc }

totalSales = completedTxns.sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
totalOrders = completedTxns.size()
avgOrderValue = totalOrders > 0 ? (totalSales / totalOrders).setScale(2, java.math.RoundingMode.HALF_UP) : BigDecimal.ZERO
totalDiscount = completedTxns.sum { (it.discountTotal ?: 0) as BigDecimal } ?: BigDecimal.ZERO
totalTax = completedTxns.sum { (it.totalTaxAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
cancelledBills = voidedTxns.size()
cancelledAmount = voidedTxns.sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO

txnIds = completedTxns.collect { it.transactionId }

// Payment breakdown
def allPayments = txnIds ? ec.entity.find("zenith.erp.pos.PosPayment")
    .condition("transactionId", "in", txnIds).list() : []

def pmColorMap = [Cash:'#4caf50', Card:'#2196f3', UPI:'#9c27b0', BankTransfer:'#ff9800', Cheque:'#607d8b']
def paymentTotals = new LinkedHashMap()
allPayments.each { p ->
    def method = p.paymentMethod ?: 'Other'
    paymentTotals[method] = (paymentTotals[method] ?: BigDecimal.ZERO) + ((p.amount ?: 0) as BigDecimal)
}
paymentBars = []
def totalPaymentAmt = paymentTotals.values().sum() ?: BigDecimal.ONE
paymentTotals.each { method, amt ->
    def pct = totalPaymentAmt > 0 ? (amt * 100 / totalPaymentAmt).intValue() : 0
    paymentBars.add([method: method, amount: ec.l10n.format(amt, '#,##0'),
        pct: pct, color: pmColorMap[method] ?: '#999'])
}

// Hourly sales breakdown
def hourlySales = new BigDecimal[24]
for (int i = 0; i < 24; i++) hourlySales[i] = BigDecimal.ZERO
completedTxns.each { t ->
    if (t.entryDate) {
        def cal = java.util.Calendar.getInstance()
        cal.setTime(t.entryDate)
        def hour = cal.get(java.util.Calendar.HOUR_OF_DAY)
        hourlySales[hour] = hourlySales[hour] + ((t.payableAmount ?: 0) as BigDecimal)
    }
}
def maxH = hourlySales.max() ?: BigDecimal.ONE
if (maxH == BigDecimal.ZERO) maxH = BigDecimal.ONE

hourlyBars = []
for (int h = 0; h < 24; h++) {
    def val = hourlySales[h]
    def pct = (val * 100 / maxH).intValue()
    if (pct < 3 && val > 0) pct = 3
    def label = ''
    if (val > 0) {
        label = val >= 1000 ? ec.l10n.format(val / 1000, '#0.#') + 'k' : ec.l10n.format(val, '#,##0')
    }
    hourlyBars.add([hour: String.format("%d", h), pct: pct, label: label,
        hasValue: val > BigDecimal.ZERO])
}

// Top selling products
def barColors = ['#e91e63','#2196f3','#ff9800','#4caf50','#9c27b0','#00bcd4','#f44336','#3f51b5','#ff5722','#607d8b']
topProductBars = []
if (txnIds) {
    def itemList = ec.entity.find("zenith.erp.pos.PosTransactionItem")
        .condition("transactionId", "in", txnIds).list()
    def productMap = [:]
    itemList.each { item ->
        def pid = item.productName ?: item.productId
        if (!productMap[pid]) productMap[pid] = [name: pid, qty: BigDecimal.ZERO, total: BigDecimal.ZERO]
        productMap[pid].qty = productMap[pid].qty + ((item.quantity ?: 0) as BigDecimal)
        productMap[pid].total = productMap[pid].total + ((item.lineTotal ?: 0) as BigDecimal)
    }
    def sorted = productMap.values().sort { -(it.total as BigDecimal) }.take(10)
    def maxP = sorted ? (sorted[0].total as BigDecimal) : BigDecimal.ONE
    if (maxP == BigDecimal.ZERO) maxP = BigDecimal.ONE
    sorted.eachWithIndex { p, idx ->
        def pct = (p.total * 100 / maxP).intValue()
        topProductBars.add([name: p.name, total: ec.l10n.format(p.total, '#,##0'),
            qty: ec.l10n.format(p.qty, '#,##0'), pct: pct,
            color: barColors[idx % barColors.size()]])
    }
}

lastBillNumber = completedTxns ? completedTxns.last().transactionNumber : '-'
lastBillAmount = completedTxns ? ec.l10n.format(completedTxns.last().payableAmount ?: 0, '#,##0.00') : '0.00'

// Expenses today
todayExpenses = BigDecimal.ZERO
try {
    def _eq = ec.entity.find("zenith.erp.pos.PosExpense")
        .condition("expenseDate", "greater-equals", dayStart)
        .condition("expenseDate", "less-equals", dayEnd)
    if (_locSessionIds) _eq.condition("sessionId", "in", _locSessionIds)   // ZE-SHOP: scope by selected shop
    def expList = _eq.list()
    todayExpenses = expList.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
} catch (Exception e) { /* entity may not exist yet */ }

// Cash In/Out today
todayCashIn = BigDecimal.ZERO
todayCashOut = BigDecimal.ZERO
try {
    def _cq = ec.entity.find("zenith.erp.pos.PosCashEntry")
        .condition("entryDate", "greater-equals", dayStart)
        .condition("entryDate", "less-equals", dayEnd)
    if (_locSessionIds) _cq.condition("sessionId", "in", _locSessionIds)   // ZE-SHOP: scope by selected shop
    def cashList = _cq.list()
    todayCashIn = cashList.findAll { it.entryType == 'CashIn' }.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
    todayCashOut = cashList.findAll { it.entryType == 'CashOut' }.sum { (it.amount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
} catch (Exception e) { /* entity may not exist yet */ }

// Stock alerts
zeroStockCount = 0
lowStockCount = 0
try {
    def stockList = ec.entity.find("zenith.erp.inventory.ProductStockView").list()
    zeroStockCount = stockList.count { (it.totalQoh ?: 0) <= 0 }
    lowStockCount = stockList.count { def qoh = (it.totalQoh ?: 0) as BigDecimal; def rp = (it.reorderPoint ?: 0) as BigDecimal; qoh > 0 && rp > 0 && qoh <= rp }
} catch (Exception e) { /* view may not exist */ }

// Active KOTs
activeKotCount = 0
try {
    activeKotCount = ec.entity.find("zenith.erp.pos.KitchenOrderTicket")
        .condition("statusId", "in", ["KotNew", "KotPreparing", "KotReady"]).count() as int
} catch (Exception e) { /* entity may not exist */ }

// Wastage today
todayWastage = BigDecimal.ZERO
try {
    def wList = ec.entity.find("zenith.erp.pos.PosStockWastage")
        .condition("wastageDate", "greater-equals", dayStart)
        .condition("wastageDate", "less-equals", dayEnd).list()
    todayWastage = wList.sum { (it.totalLoss ?: 0) as BigDecimal } ?: BigDecimal.ZERO
} catch (Exception e) { /* entity may not exist */ }

// Active sessions
activeSessions = 0
try {
    activeSessions = ec.entity.find("zenith.erp.pos.PosSession")
        .condition("statusId", "PsOpen").count() as int
} catch (Exception e) {}

// ===== Business Health scorecard (ZcERP report v2.1.0) — a COMPOSITE 0-100 score computed from
// REAL live data (never a fabricated number). Each of 5 metrics scores 0-100; a metric with no data
// for the current context is marked "No data" and EXCLUDED from the average, so a zero-sales day
// never fakes a low score. Sales & Cash Flow follow the selected date range; Receivables, Inventory
// and GST are current snapshots. =====
healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e'
try {
    def _orgH = ec.user.getPreference("ACTIVE_ORGANIZATION")
    def _nowH = ec.user.nowTimestamp
    def _pill = [good:['#DCFCE7','#166534'], warn:['#FEF3C7','#92400E'], bad:['#FEE2E2','#991B1B'], na:['#EEF0F5','#64748B']]
    def _col = { s -> s >= 80 ? 'good' : (s >= 55 ? 'warn' : 'bad') }
    def _add = { name, avail, score, status, ck -> def p = _pill[ck] ?: _pill.na; healthMetrics.add([name:name, avail:avail, score:score, status:status, pillBg:p[0], pillFg:p[1]]) }

    // prior equal-length period (for the Sales trend)
    def _pDays = (long)(((dayEnd.getTime() - dayStart.getTime()) / (1000L*60*60*24)) + 1)
    def _priorStart = new java.sql.Timestamp(dayStart.getTime() - _pDays*24L*60*60*1000)
    def _priorSales = BigDecimal.ZERO
    if (_orgH) {
        def _pq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
            .condition("statusId","PtCompleted").condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, _priorStart)
            .condition("entryDate", org.moqui.entity.EntityCondition.LESS_THAN, dayStart)
        if (_locSessionIds) _pq.condition("sessionId","in",_locSessionIds)  // only scope to a location when one is picked
        _priorSales = _pq.list().sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
    }

    // 1) SALES — this period vs the prior equal-length period
    if (totalSales <= 0 && _priorSales <= 0) { _add('Sales', false, 0, 'No sales in range', 'na') }
    else {
        double _g = _priorSales > 0 ? ((totalSales.doubleValue() - _priorSales.doubleValue()) * 100.0 / _priorSales.doubleValue()) : (totalSales > 0 ? 100.0 : -100.0)
        def _s = _g >= 10 ? 95 : (_g >= 0 ? 80 : (_g >= -15 ? 60 : 35))
        def _st = _g >= 10 ? 'Strong' : (_g >= 0 ? 'Good' : (_g >= -15 ? 'Fair' : 'Weak'))
        def _gp = Math.round(_g)
        _add('Sales', true, _s, _st + ' (' + (_gp >= 0 ? '+' : '') + _gp + '% vs prior)', _col(_s))
    }

    // 2) CASH FLOW — how much of sales is eaten by expenses + wastage (period)
    if (totalSales <= 0) { _add('Cash Flow', false, 0, 'No sales in range', 'na') }
    else {
        def _out = ((todayExpenses ?: 0) as BigDecimal) + ((todayWastage ?: 0) as BigDecimal)
        double _r = (_out.doubleValue() * 100.0 / totalSales.doubleValue())
        def _s = _r < 5 ? 95 : (_r < 15 ? 80 : (_r < 30 ? 60 : 35))
        def _st = _r < 5 ? 'Strong' : (_r < 15 ? 'Healthy' : (_r < 30 ? 'Watch' : 'Tight'))
        _add('Cash Flow', true, _s, _st, _col(_s))
    }

    // reference: 90-day sales (denominator for the receivables ratio)
    def _c90 = java.util.Calendar.getInstance(); _c90.setTime(_nowH); _c90.add(java.util.Calendar.DAY_OF_MONTH, -90)
    def _ref90 = BigDecimal.ZERO
    if (_orgH) {
        def _rq = ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
            .condition("statusId","PtCompleted").condition("entryDate", org.moqui.entity.EntityCondition.GREATER_THAN_EQUAL_TO, new java.sql.Timestamp(_c90.getTimeInMillis()))
        if (_locSessionIds) _rq.condition("sessionId","in",_locSessionIds)
        _ref90 = _rq.list().sum { (it.payableAmount ?: 0) as BigDecimal } ?: BigDecimal.ZERO
    }

    // 3) RECEIVABLES — outstanding on credit bills (payable - paid), current
    def _creditOut = BigDecimal.ZERO
    if (_orgH) {
        ec.entity.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", _orgH)
            .condition("isCredit","Y").condition("statusId","PtCompleted").list().each {
                def _py = (it.payableAmount ?: 0) as BigDecimal; def _pd = (it.paidAmount ?: 0) as BigDecimal
                if (_py > _pd) _creditOut += (_py - _pd)
            }
    }
    if (_creditOut <= 0) { _add('Receivables', true, 100, 'Nothing outstanding', 'good') }
    else {
        double _r = _ref90 > 0 ? (_creditOut.doubleValue() / _ref90.doubleValue()) : 1.0
        def _s = _r < 0.02 ? 95 : (_r < 0.10 ? 80 : (_r < 0.25 ? 55 : 30))
        def _st = _r < 0.02 ? 'Healthy' : (_r < 0.10 ? 'OK' : (_r < 0.25 ? 'Needs Attention' : 'High'))
        _add('Receivables', true, _s, _st + ' (' + ec.l10n.format(_creditOut, '#,##0') + ' owed)', _col(_s))
    }

    // product-based snapshots (Inventory + GST)
    def _prodTot = _orgH ? ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).count() : 0
    if (_prodTot > 0) {
        def _tracked = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition("inventoryTracked","Y").count()
        // 4) INVENTORY — stock health when tracked, else catalog readiness (priced items ready to sell)
        if (_tracked >= 5) {
            def _r = ((zeroStockCount + lowStockCount) * 1.0 / _tracked)
            def _s = _r < 0.05 ? 95 : (_r < 0.15 ? 80 : (_r < 0.30 ? 55 : 30))
            def _st = _r < 0.05 ? 'Healthy' : (_r < 0.15 ? 'Good' : (_r < 0.30 ? 'Needs Attention' : 'Low'))
            _add('Inventory', true, _s, _st, _col(_s))
        } else {
            def _wp = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition("mrpAmount", org.moqui.entity.EntityCondition.GREATER_THAN, 0G).count()
            def _r = (_wp * 1.0 / _prodTot)
            def _s = _r >= 0.95 ? 90 : (_r >= 0.80 ? 75 : (_r >= 0.50 ? 55 : 35))
            def _st = _r >= 0.80 ? 'Catalog ready' : (_r >= 0.50 ? 'Some unpriced' : 'Many unpriced')
            _add('Inventory', true, _s, _st, _col(_s))
        }
        // 5) GST — % of products with a GST slab / HSN / exempt flag
        def _cf = ec.entity.conditionFactory
        def _gstCond = _cf.makeCondition([
            _cf.makeCondition("gstSlabId", org.moqui.entity.EntityCondition.IS_NOT_NULL, null),
            _cf.makeCondition("isGstExempt", org.moqui.entity.EntityCondition.EQUALS, "Y"),
            _cf.makeCondition("hsnCode", org.moqui.entity.EntityCondition.IS_NOT_NULL, null)
        ], org.moqui.entity.EntityCondition.OR)
        def _gstOk = ec.entity.find("mantle.product.Product").condition("ownerPartyId", _orgH).condition(_gstCond).count()
        def _r = (_gstOk * 1.0 / _prodTot)
        def _s = _r >= 0.95 ? 95 : (_r >= 0.80 ? 80 : (_r >= 0.50 ? 55 : 30))
        def _st = _r >= 0.95 ? 'Compliant' : (_r >= 0.80 ? 'Mostly set' : (_r >= 0.50 ? 'Partial' : 'Needs setup'))
        _add('GST', true, _s, _st, _col(_s))
    }

    def _avail = healthMetrics.findAll { it.avail }
    healthHasData = (_avail.size() > 0)
    healthScore = healthHasData ? (int) Math.round(_avail.sum { it.score } / _avail.size()) : 0
    healthLabel = healthScore >= 85 ? 'Excellent' : (healthScore >= 70 ? 'Good' : (healthScore >= 55 ? 'Fair' : 'Needs Work'))
    healthColor = healthScore >= 85 ? '#16A34A' : (healthScore >= 70 ? '#65A30D' : (healthScore >= 55 ? '#D97706' : '#DC2626'))
} catch (Exception e) { healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e' }

// SaaS module-access flags: hide ERP-module links not in the tenant's plan
def _mods = context.saasAllowedModules
boolean _allMod = (context.saasHasAllAccess == true) || (context.isSaasTenant != true)
modSales = _allMod || (_mods != null && _mods.contains('sales'))
modInventory = _allMod || (_mods != null && _mods.contains('inventory'))
modContacts = _allMod || (_mods != null && _mods.contains('contacts'))
modAccounting = _allMod || (_mods != null && _mods.contains('accounting'))
modPurchase = _allMod || (_mods != null && _mods.contains('purchase'))

// ZE-DASH-02/03: per-user switchable widgets + role-based defaults.
// Role default applies ONLY when the user has never customized (pref == null). A POS-only cashier
// (sole ZENITH_ role = ZENITH_CASHIER, not super-admin — same test the Terminal uses) gets a lean
// view: Sales KPIs + Payment Breakdown; owners/managers/admin see everything.
def _roleHidden = ''
try {
    if (!ec.user.isInGroup("ADMIN")) {
        def _zrp = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }
        if (_zrp.size() == 1 && _zrp.contains("ZENITH_CASHIER")) _roleHidden = 'opsKpi,hourly,products,health'
    }
} catch (Exception e) {}
def _prefRaw = ec.user.getPreference('POS_DASH_HIDDEN')
def _hiddenPref = (_prefRaw != null) ? _prefRaw : _roleHidden
def _hiddenSet = _hiddenPref.split(',').findAll { it }.toSet()
showSalesKpi = !_hiddenSet.contains('salesKpi')
showOpsKpi   = !_hiddenSet.contains('opsKpi')
showHealth   = !_hiddenSet.contains('health')
showHourly   = !_hiddenSet.contains('hourly')
showPayments = !_hiddenSet.contains('payments')
showProducts = !_hiddenSet.contains('products')
w_salesKpi = showSalesKpi ? 'Y' : ''
w_opsKpi   = showOpsKpi ? 'Y' : ''
w_health   = showHealth ? 'Y' : ''
w_hourly   = showHourly ? 'Y' : ''
w_payments = showPayments ? 'Y' : ''
w_products = showProducts ? 'Y' : ''
// ZE-DASH-03: saved widget order (JS applies it on load + drag-to-reorder saves it back)
dashOrderCsv = (ec.user.getPreference('POS_DASH_ORDER') ?: '')
isDefaultDashPos = (ec.user.getPreference('DEFAULT_DASHBOARD') == 'pos')
isTeamDefaultPos = false; canSetTeamPos = false
try {
    def _o2 = ec.user.getPreference('ACTIVE_ORGANIZATION')
    if (ec.user.isInGroup("ADMIN")) canSetTeamPos = true
    else { def _z2 = (ec.user.userGroupIdSet ?: []).findAll { it?.startsWith("ZENITH_") && it != "ZENITH_ALL" }; canSetTeamPos = !(_z2.size()==1 && _z2.contains("ZENITH_CASHIER")) }
    if (_o2 && _o2 != '_NA_') { def _oc2 = ec.entity.find("zenith.erp.pos.OrgDashboardDefault").condition("organizationPartyId", _o2).one(); isTeamDefaultPos = (_oc2?.dashboardKey == 'pos') }
} catch (Exception e) {}
